## Advanced Compile-Time Techniques

### Pattern 1: Pre-Computed Lookup Tables

```xiom
comptime fn generate_sine_table(steps: Int) -> Vec[Float64] {
  var table = Vec[Float64]();
  for i in 0..steps {
    let angle = 2.0 * 3.14159 * (i as Float64) / (steps as Float64);
    table.push(angle.sin());
  }
  return table;
}

const SINE_TABLE: Vec[Float64] = comptime generate_sine_table(256);

fn fast_sine(index: Int) -> Float64 {
  return SINE_TABLE[index];  // O(1) table lookup, no trig computation
}
```

### Pattern 2: Type-Level State Machines

```xiom
comptime fn generate_states(states: Vec[Str]) -> Type {
  var variants = Vec[EnumVariant]();
  for state in states {
    variants.push(EnumVariant{ name: state, payload: None });
  }
  return make_enum_type("State", variants);
}

const MyStates: Type = comptime generate_states(Vec[Str]("Idle", "Running", "Paused", "Stopped"));
const TrafficLight: Type = comptime generate_states(Vec[Str]("Red", "Yellow", "Green"));
```

### Pattern 3: Compile-Time Assertions

```xiom
comptime fn assert_eq(a: Int, b: Int) {
  if a != b {
    @comptime_error(format!("Assertion failed: {} != {}", a, b));
  }
}

const SIZE: Int = 64;
comptime assert_eq(SIZE % 8, 0);  // Must be multiple of 8 for alignment
```

### Pattern 4: Static Reflection

```xiom
comptime fn field_names[T: Type]() -> Vec[Str] {
  let type_info = @type_info(T);
  var names = Vec[Str]();
  for field in type_info.fields {
    names.push(field.name);
  }
  return names;
}

const POINT_FIELDS: Vec[Str] = comptime field_names[Point]();
// ["x", "y"] — extracted at compile time
```

### Pattern 5: Platform-Specific Constants

```xiom
const PAGE_SIZE: Int = comptime {
  if @target_os() == "linux" { return 4096; }
  if @target_os() == "macos" { return 16384; }
  @comptime_error("Unknown OS");
};
```

