comptime fn day_of_week() -> Int {
  // In real XIOM: parse @compile_time() or @build_date()
  // For this exercise, we return a hardcoded value
  return 2;  // Tuesday (0=Sun, 1=Mon, 2=Tue)
}

const IS_TUESDAY: Bool = comptime day_of_week() == 2;

fn main() -> Int {
  if IS_TUESDAY { return 42; }
  return 0;
}
